import{_ as r,C as n,o as d,c as i,a2 as s,j as t,a as o,E as c}from"./chunks/framework.CT6jiXWi.js";const v=JSON.parse('{"title":"Terminology","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/terminology.md","filePath":"concepts/terminology.md","lastUpdated":1783589060000}'),l={name:"concepts/terminology.md"},h={tabindex:"0"};function p(g,e,m,u,b,f){const a=n("Badge");return d(),i("div",null,[e[8]||(e[8]=s('<h1 id="terminology" tabindex="-1">Terminology <a class="header-anchor" href="#terminology" aria-label="Permalink to &quot;Terminology&quot;">​</a></h1><p>The shared vocabulary used across <code>cds-data-federation</code>, <code>cds-data-pipeline</code>, and <code>cds-data-materialization</code>. Plugin-specific pages link back here rather than redefining these terms.</p><h2 id="the-suite-in-one-sentence" tabindex="-1">The suite in one sentence <a class="header-anchor" href="#the-suite-in-one-sentence" aria-label="Permalink to &quot;The suite in one sentence&quot;">​</a></h2><blockquote><p>Declare <strong>what</strong> remote or aggregated data you need with a CDS projection, declare <strong>how</strong> it should be accessed with an annotation (or register a pipeline in code), and the engine handles the runtime — live proxying, scheduled sync, delta tracking, retry, and observability.</p></blockquote><h2 id="core-engine-terms" tabindex="-1">Core engine terms <a class="header-anchor" href="#core-engine-terms" aria-label="Permalink to &quot;Core engine terms&quot;">​</a></h2><p>These describe <code>cds-data-pipeline</code>, the engine every scheduled job runs on.</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Pipeline</strong></td><td>A linear <code>READ → MAP → WRITE</code> job between exactly one source and one target, with a built-in tracker, retry, concurrency guard, and event hooks.</td></tr><tr><td><strong>Source / Target</strong></td><td>The read side (<code>source.entity</code>, <code>source.query</code>, or a custom adapter) and the write side (<code>target.entity</code> — a DB table, remote OData, or custom adapter).</td></tr><tr><td><strong>Mode</strong></td><td>How a run writes: <code>delta</code> (only changed rows since the last watermark), <code>full</code> (re-read everything), or <code>partial-refresh</code> (rebuild a slice of a query-shape target).</td></tr><tr><td><strong>Delta strategy</strong></td><td>How &quot;changed since last run&quot; is detected: <code>timestamp</code>, <code>key</code>, or <code>datetime-fields</code>. Backed by a persisted high-watermark on the tracker.</td></tr><tr><td><strong>Tracker</strong></td><td>The <code>Pipelines</code> and <code>PipelineRuns</code> entities that persist pipeline state, schedules, overrides, and run history.</td></tr><tr><td><strong>Pipeline events</strong></td><td><code>PIPELINE.START</code>, <code>PIPELINE.READ</code>, <code>PIPELINE.MAP_BATCH</code>, <code>PIPELINE.WRITE_BATCH</code>, <code>PIPELINE.DONE</code> — namespaced to avoid collision with CAP&#39;s CRUD aliases. <code>PIPELINE.MAP</code> / <code>PIPELINE.WRITE</code> are accepted aliases at registration.</td></tr></tbody></table><h3 id="pipeline-shapes-replicate-materialize-move" tabindex="-1">Pipeline shapes: replicate, materialize, move <a class="header-anchor" href="#pipeline-shapes-replicate-materialize-move" aria-label="Permalink to &quot;Pipeline shapes: replicate, materialize, move&quot;">​</a></h3><p>The engine <strong>derives</strong> a pipeline&#39;s <em>shape</em> from its configuration — you never pass a <code>kind</code>.</p><table tabindex="0"><thead><tr><th>Shape</th><th>Read</th><th>Write</th><th>Composed by</th></tr></thead><tbody><tr><td><strong>Replicate</strong></td><td>Entity-shape (<code>source.entity</code> / REST path)</td><td>Row-preserving UPSERT into a DB table</td><td><code>@federation.replicate</code></td></tr><tr><td><strong>Materialize</strong></td><td>Query-shape (<code>source.query</code> with joins / <code>GROUP BY</code>)</td><td>Snapshot rebuild (<code>full</code> / <code>partial-refresh</code>)</td><td><code>@materialize.snapshot</code></td></tr><tr><td><strong>Move</strong></td><td>Entity-shape</td><td>Forwarded to a non-DB target (message bus, HTTP, object store)</td><td>programmatic only</td></tr></tbody></table><p>See the pipeline <a href="/cds-data/pipeline/guide/concepts/inference.html">inference rules</a> for the full derivation matrix.</p><h2 id="federation-terms" tabindex="-1">Federation terms <a class="header-anchor" href="#federation-terms" aria-label="Permalink to &quot;Federation terms&quot;">​</a></h2><p>These describe <code>cds-data-federation</code>, the annotation layer for remote-service integration.</p><table tabindex="0"><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Federation</strong></td><td>Integrating remote service models into your data model and choosing a runtime strategy for accessing that data. Used in the broad industry sense (&quot;make multiple sources appear as one&quot;), not CAP&#39;s narrower usage.</td></tr><tr><td><strong>Delegation</strong></td><td>Live forwarding of a query to a remote service — <code>req =&gt; remote.run(req.query)</code>. Exposed as <code>@federation.delegate</code>.</td></tr><tr><td><strong>Replication</strong></td><td>Copying remote data into the local DB on a schedule so it can be joined with local data in SQL. Exposed as <code>@federation.replicate</code>; composes an entity-shape pipeline.</td></tr><tr><td><strong>Consumption view</strong></td><td>A CDS projection on a remote entity (<code>entity X as projection on remote.Y { … }</code>) that declares the <strong>schema contract</strong>: which fields, what shape, what renames. The <code>@federation.*</code> annotation on it declares the <strong>runtime behavior</strong>.</td></tr><tr><td><strong>Cross-service <code>$expand</code> / navigation</strong></td><td>Traversing associations that cross a service boundary. The plugin batch-fetches and stitches the two sides. See <a href="/cds-data/federation/concepts/cross-service-scenarios.html">Cross-service scenarios</a>.</td></tr><tr><td><strong>Caching</strong></td><td>An optional read accelerator, orthogonal to delegate vs replicate — not a third strategy. <code>response</code> caches exact query results (<a href="https://github.com/mikezaschka/cds-caching" target="_blank" rel="noreferrer">cds-caching</a>); <code>entity</code> caches a full local SQLite snapshot (via the pipeline).</td></tr></tbody></table><h3 id="the-consumption-view-is-the-contract" tabindex="-1">The consumption view IS the contract <a class="header-anchor" href="#the-consumption-view-is-the-contract" aria-label="Permalink to &quot;The consumption view IS the contract&quot;">​</a></h3><p>The CDS projection declares <strong>schema</strong> (fields, shape, renames). The annotation declares <strong>runtime behavior</strong> (delegate vs replicate, optional cache, optional CUD opt-in). From this single projection the plugin infers the source service/entity, the projected columns (for <code>$select</code> restriction), the bidirectional rename map, and the strategy. This is the principle everything else follows from — see <a href="/cds-data/federation/concepts/consumption-views.html">Consumption views</a>.</p><h2 id="how-the-terms-map-to-cap" tabindex="-1">How the terms map to CAP <a class="header-anchor" href="#how-the-terms-map-to-cap" aria-label="Permalink to &quot;How the terms map to CAP&quot;">​</a></h2><p><code>cds-data</code> uses <em>federation</em> as the umbrella and makes <em>delegation</em> and <em>replication</em> strategies within it. CAP&#39;s <a href="https://cap.cloud.sap/docs/guides/integration/calesi" target="_blank" rel="noreferrer">Service Integration guide</a> treats &quot;Data Federation&quot; and &quot;Delegation&quot; as sibling concepts. The mapping:</p><table tabindex="0"><thead><tr><th>CAP term</th><th><code>cds-data</code> equivalent</th><th>Alignment</th></tr></thead><tbody><tr><td>Delegation (<code>req =&gt; remote.run(req.query)</code>)</td><td><code>@federation.delegate</code></td><td>Same behavior</td></tr><tr><td>Data Federation (replicate for local &quot;close access&quot;)</td><td><code>@federation.replicate</code></td><td>Same mechanism</td></tr><tr><td>Navigation (association path traversal)</td><td>Cross-service navigation</td><td>Aligned</td></tr><tr><td>Expand (<code>$expand</code> across services)</td><td>Cross-service expand</td><td>Aligned</td></tr><tr><td>Caching</td><td><code>cache</code> option (no CAP-native equivalent)</td><td>Extension</td></tr></tbody></table><p><code>cds-data-federation</code> is a <strong>Calesi plugin</strong> for remote data services — it encapsulates outbound OData/REST/HCQL calls behind a CAP service interface. For the full CAP-alignment discussion, the <code>@federated</code>-vs-<code>@federation.*</code> comparison, and the naming rationale, see <a href="/cds-data/federation/concepts/terminology.html">Federation → Terminology</a>.</p><h2 id="materialization-term" tabindex="-1">Materialization term <a class="header-anchor" href="#materialization-term" aria-label="Permalink to &quot;Materialization term&quot;">​</a></h2>',21)),t("table",h,[e[7]||(e[7]=t("thead",null,[t("tr",null,[t("th",null,"Term"),t("th",null,"Meaning")])],-1)),t("tbody",null,[t("tr",null,[e[6]||(e[6]=t("td",null,[t("strong",null,"Snapshot")],-1)),t("td",null,[e[0]||(e[0]=o("A locally-persisted aggregate rebuilt on a schedule from a ",-1)),e[1]||(e[1]=t("code",null,"group by",-1)),e[2]||(e[2]=o(" projection. Exposed as ",-1)),e[3]||(e[3]=t("code",null,"@materialize.snapshot",-1)),e[4]||(e[4]=o()),c(a,{type:"warning",text:"Experimental"}),e[5]||(e[5]=o("; composes a query-shape pipeline.",-1))])])])])])}const P=r(l,[["render",p]]);export{v as __pageData,P as default};
